' + tasksBlock.split('
').slice(0, 20).join('
') + '

=== SYSTEM HEALTH ===
' + healthBlock + '

Respond in this exact JSON shape (no markdown, no preamble):
{
  "home_summary": { "headline": "...", "body": "...", "recommended_focus": "..." },
  "home_metrics": [ { "id": "...", "label": "...", "value": "...", "target": "...", "status": "...", "progress_pct": 0, "interpretation": "..." } ],
  "home_external_signals": [ { "signal": "...", "source": "...", "relevance": "...", "recommended_action": "..." } ],
  "home_customer_signals": [ { "product": "gutted|onalert|merciless|fractionl_circle|fractionl_pulse|mm_ctrl", "paid_added": 0, "churned": 0, "mrr_delta": 0, "free_added": 0, "top_source": null } ],
