const anthropic_body = {
  model: 'claude-sonnet-4-6',
  max_tokens: mode === 'deep' ? 3500 : 1200,
  messages: [{ role: 'user', content: prompt }]
};

const gemini_body = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { maxOutputTokens: mode === 'deep' ? 3500 : 1200, temperature: 0.6 }
};

return [{
  json: {
    mode,
    week_of: s.week_of,
    started_at: s.started_at,
    prompt_length: prompt.length,
    anthropic_body,
    gemini_body
  }
}];

// Defensive: LLM could be Anthropic success OR Gemini fallback
// Previous version called $('Gemini Flash Fallback') via helper which threw an Error
// that the n8n runtime couldn't properly catch/mutate, producing:
// "Cannot assign to read only property 'name' of object 'Error: Node ... hasn't been executed'"
//
// Fix: read from $input (merged upstream) and detect shape rather than querying by node name.

const inputJson = $input.first().json || {};
const ctx = $('Build Prompt').first().json;
const mode = ctx.mode;
const weekOf = ctx.week_of;
const startedAt = ctx.started_at;

// Detect shape. Anthropic response has { content: [{text: ...}], usage: {...}, model: ... }
// Gemini response has { candidates: [{ content: { parts: [{text: ...}] } }] }
let text = '';
let modelUsed = null;
let anthropicRaw = null;
let geminiRaw = null;

if (inputJson.content && Array.isArray(inputJson.content) && inputJson.content[0] && inputJson.content[0].text) {
  anthropicRaw = inputJson;
  text = inputJson.content[0].text;
  modelUsed = (ctx.anthropic_body && ctx.anthropic_body.model) || 'claude-sonnet';
} else if (inputJson.candidates && inputJson.candidates[0] && inputJson.candidates[0].content && inputJson.candidates[0].content.parts && inputJson.candidates[0].content.parts[0] && inputJson.candidates[0].content.parts[0].text) {
  geminiRaw = inputJson;
  text = inputJson.candidates[0].content.parts[0].text;
  modelUsed = 'gemini-2.5-flash';
}

function extractJson(s) {
  if (!s) return null;
  const clean = s.replace(/```json|```/g, '').trim();
  const first = clean.indexOf('{');
  const last = clean.lastIndexOf('}');
  if (first === -1 || last === -1 || last <= first) return null;
  try { return JSON.parse(clean.slice(first, last + 1)); } catch (e) { return null; }
}

const parsed = extractJson(text) || {};

const insights = Array.isArray(parsed.insights) ? parsed.insights : [];
const orgFocus = parsed.org_focus || '';
const cleoRec = parsed.cleo_recommendation || '';
const homeSummary = parsed.home_summary || null;
const homeMetrics = Array.isArray(parsed.home_metrics) ? parsed.home_metrics : [];
const homeSignals = Array.isArray(parsed.home_external_signals) ? parsed.home_external_signals : [];
const homeCustomerSignals = Array.isArray(parsed.home_customer_signals) ? parsed.home_customer_signals : [];
const homeCustomerVoice = Array.isArray(parsed.home_customer_voice) ? parsed.home_customer_voice : (Array.isArray(parsed.customer_voice) ? parsed.customer_voice : []);

const durationMs = Date.now() - new Date(startedAt).getTime();

const inputTokens = (anthropicRaw && anthropicRaw.usage && anthropicRaw.usage.input_tokens) || 0;
const outputTokens = (anthropicRaw && anthropicRaw.usage && anthropicRaw.usage.output_tokens) || 0;
let costEstimateUsd = 0;
if (modelUsed && modelUsed.indexOf('sonnet') !== -1) {
  costEstimateUsd = (inputTokens / 1000000) * 3 + (outputTokens / 1000000) * 15;
} else if (modelUsed && modelUsed.indexOf('gemini') !== -1) {
  costEstimateUsd = (inputTokens / 1000000) * 0.075 + (outputTokens / 1000000) * 0.3;
}
costEstimateUsd = Math.round(costEstimateUsd * 10000) / 10000;

const ok = (mode === 'deep' ? insights.length >= 1 && homeSummary !== null : homeSummary !== null);

return [{
  json: {
    mode,
    week_of: weekOf,
    started_at: startedAt,
    model_used: modelUsed || 'none',
    ok,
    insights,
    org_focus: orgFocus,
    cleo_recommendation: cleoRec,
    home_summary: homeSummary,
    home_metrics: homeMetrics,
    home_external_signals: homeSignals,
    home_customer_signals: homeCustomerSignals,
    home_customer_voice: homeCustomerVoice,
    raw_text: text.slice(0, 2000),
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cost_estimate_usd: costEstimateUsd,
    duration_ms: durationMs
  }
}];

