const SB_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SB_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const H = { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' };
const H_UPSERT = { ...H, 'Prefer': 'resolution=merge-duplicates,return=minimal' };

const d = $input.first().json;
const writesLog = { home_intelligence: false, marcus_synthesis: false, agatha_task: false, audit_log: false, workflow_runs: false };

if (!d.ok || !d.home_summary) {
  writesLog.error = 'LLM parse failed or empty, skipping Supabase writes';
  return [{ json: { ...d, writes: writesLog } }];
}

// === Compute customer_signals and overdue lead follow-ups directly from DB ===
// Brief tells Marcus to roll these up from customers/leads tables, but the
// synthesis LLM has no DB tool. Computing deterministically here so the
// brief's intent actually materialises on home_intelligence.
let computedCustomerSignals = [];
try {
  const sevenDaysAgo = new Date(Date.now() - 7*24*3600*1000).toISOString();
  const customersUrl = SB_URL + '/rest/v1/customers?select=product,kind,mrr_usd,source,became_paid_at,churned_at,signed_up_at&or=(became_paid_at.gte.' + encodeURIComponent(sevenDaysAgo) + ',churned_at.gte.' + encodeURIComponent(sevenDaysAgo) + ',signed_up_at.gte.' + encodeURIComponent(sevenDaysAgo) + ')';
  const customers = await __httpRequest({ method: 'GET', url: customersUrl, headers: H });
  const byProduct = {};
  for (const c of (customers || [])) {
    const p = c.product;
    if (!byProduct[p]) byProduct[p] = { product: p, paid_added: 0, churned: 0, mrr_delta: 0, free_added: 0, sources: {} };
    const b = byProduct[p];
    if (c.became_paid_at && c.became_paid_at >= sevenDaysAgo) {
      b.paid_added += 1;
      b.mrr_delta += Number(c.mrr_usd || 0);
      if (c.source) b.sources[c.source] = (b.sources[c.source] || 0) + 1;
    }
    if (c.churned_at && c.churned_at >= sevenDaysAgo) {
      b.churned += 1;
      b.mrr_delta -= Number(c.mrr_usd || 0);
    }
    if (c.signed_up_at && c.signed_up_at >= sevenDaysAgo && c.kind === 'free_signup') {
      b.free_added += 1;
    }
  }
  computedCustomerSignals = Object.values(byProduct).map(b => ({
    product: b.product,
    paid_added: b.paid_added,
    churned: b.churned,
    mrr_delta: Math.round(b.mrr_delta * 100) / 100,
    free_added: b.free_added,
    top_source: Object.entries(b.sources).sort((a,b) => b[1]-a[1])[0]?.[0] || null
  }));
} catch (e) { writesLog.customer_signals_error = String(e).slice(0, 200); }

let overdueLeadSignals = [];
try {
  const nowIso = new Date().toISOString();
  const leadsUrl = SB_URL + '/rest/v1/leads?select=id,full_name,company,why_relevant,next_step,follow_up_at&follow_up_at=lt.' + encodeURIComponent(nowIso) + '&status=in.(ready,contacted,conversation)&order=follow_up_at.asc&limit=3';
  const overdueLeads = await __httpRequest({ method: 'GET', url: leadsUrl, headers: H });
  for (const l of (overdueLeads || [])) {
    const days = Math.round((new Date(l.follow_up_at).getTime() - Date.now()) / (24*3600*1000));
    overdueLeadSignals.push({
      signal: 'Follow up: ' + (l.full_name || 'unnamed lead') + ' - ' + (l.company || 'unknown company'),
      source: 'Leads',
      relevance: l.why_relevant || 'Lead awaiting next touch',
      recommended_action: l.next_step || 'Re-engage with a one-line update',
      urgency: 'high',
      days_until: days,
      event_id: l.id
    });
  }
} catch (e) { writesLog.overdue_leads_error = String(e).slice(0, 200); }

const mergedExternalSignals = [...overdueLeadSignals, ...(d.home_external_signals || [])];
// === end deterministic signals ===

const homePayload = {
  id: 'current',
  assessment: d.mode === 'deep' ? (d.insights.join(' | ') || null) : null,
  summary: JSON.stringify(d.home_summary),
  metrics: d.home_metrics,
  external_signals: mergedExternalSignals,
  customer_signals: computedCustomerSignals.length ? computedCustomerSignals : (d.home_customer_signals || []),
  customer_voice: d.home_customer_voice || [],
  generated_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
};
try {
  await __httpRequest({ method: 'POST', url: SB_URL + '/rest/v1/home_intelligence?on_conflict=id', headers: H_UPSERT, body: JSON.stringify(homePayload) });
  writesLog.home_intelligence = true;
} catch (e) { writesLog.home_intelligence_error = String(e).slice(0, 200); }

if (d.mode === 'deep') {
  const synthPayload = {
    week_of: d.week_of,
    insights: d.insights,
    cleo_recommendations: d.cleo_recommendation,
    org_focus: d.org_focus,
    generated_at: new Date().toISOString()
  };
  try {
    await __httpRequest({ method: 'POST', url: SB_URL + '/rest/v1/marcus_synthesis', headers: H, body: JSON.stringify(synthPayload) });
    writesLog.marcus_synthesis = true;
  } catch (e) { writesLog.marcus_synthesis_error = String(e).slice(0, 200); }

  const taskPayload = {
    agent: 'agatha',
    venture: 'mindmaker-os',
    title: 'Marcus Weekly Synthesis Ready — week of ' + d.week_of,
    description: 'Marcus has produced weekly synthesis. Org focus: ' + d.org_focus + '\n\nInsights:\n' + (d.insights || []).map((x, i) => (i + 1) + '. ' + x).join('\n') + '\n\nCleo angle: ' + d.cleo_recommendation,
    status: 'active',
    priority: 'high',
    next_step: 'Review insights, route to Cleo and Leo, decide escalation to Krish',
    workstream: 'marcus-synthesis',
    created: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };
  try {
    await __httpRequest({ method: 'POST', url: SB_URL + '/rest/v1/tasks', headers: H, body: JSON.stringify(taskPayload) });
    writesLog.agatha_task = true;
  } catch (e) { writesLog.agatha_task_error = String(e).slice(0, 200); }
}


if (d.mode === 'deep' && d.agent_plans && Array.isArray(d.agent_plans)) {
  writesLog.agent_plans = 0;
  for (const plan of d.agent_plans) {
    if (!plan.agent_id) continue;
    const planPayload = {
      agent_id: plan.agent_id,
      current_phase: plan.current_phase || 'Active',
      objective: plan.objective || 'Support weekly goals',
      next_milestone: plan.next_milestone || 'Complete weekly sprint',
      updated_at: new Date().toISOString()
    };
    try {
      await __httpRequest({ method: 'POST', url: SB_URL + '/rest/v1/agent_plans?on_conflict=agent_id', headers: H_UPSERT, body: JSON.stringify(planPayload) });
      writesLog.agent_plans++;
    } catch (e) {
      if (!writesLog.agent_plans_error) writesLog.agent_plans_error = '';
      writesLog.agent_plans_error += `[${plan.agent_id}: ${e.message}] `;
    }
  }
}

const auditPayload = {
  actor: 'marcus',
  event_type: d.mode === 'deep' ? 'monday-synthesis' : 'home-intel-update',
  target: d.mode === 'deep' ? 'marcus_synthesis+home_intelligence' : 'home_intelligence',
  details: 'mode=' + d.mode + ' week_of=' + d.week_of + ' model=' + d.model_used + ' insights=' + (d.insights || []).length + ' cost_usd=' + d.cost_estimate_usd,
  changes: { writes: writesLog, duration_ms: d.duration_ms }
};
try {
  await __httpRequest({ method: 'POST', url: SB_URL + '/rest/v1/audit_log', headers: H, body: JSON.stringify(auditPayload) });
  writesLog.audit_log = true;
} catch (e) { writesLog.audit_log_error = String(e).slice(0, 200); }

const runPayload = {
  workflow_id: 'TI1ozQbPtI69qlgO',
  workflow_name: 'OS — Marcus Synthesis + Home Intelligence',
  agent_id: 'marcus',
  run_at: d.started_at,
  duration_ms: d.duration_ms,
  api_calls: 1,
  api_calls_count: 1,
  cost_usd: d.cost_estimate_usd,
  cost_estimate_usd: d.cost_estimate_usd,
  outcome: d.mode === 'deep' ? 'synthesis+home-intel' : 'home-intel',
  outcome_count: d.mode === 'deep' ? (d.insights || []).length : d.home_metrics.length,
  status: d.ok ? 'success' : 'partial',
  metadata: { mode: d.mode, model: d.model_used, input_tokens: d.input_tokens, output_tokens: d.output_tokens, writes: writesLog }
};
try {
  await __httpRequest({ method: 'POST', url: SB_URL + '/rest/v1/workflow_runs', headers: H, body: JSON.stringify(runPayload) });
  writesLog.workflow_runs = true;
} catch (e) { writesLog.workflow_runs_error = String(e).slice(0, 200); }

return [{ json: { ...d, writes: writesLog } }];

// Build identity prepend from Agent Brief + Voice Rules + Agent Plan
const briefRaw = $('Load Agent Brief').first().json;
const voiceRaw = $('Load Voice Rules').first().json;
const planRaw  = $('Load Agent Plan').first().json;

// Handle array response from Supabase REST
const briefArr = Array.isArray(briefRaw) ? briefRaw : (briefRaw.data || [briefRaw]);
const voiceArr = Array.isArray(voiceRaw) ? voiceRaw : (voiceRaw.data || [voiceRaw]);
const planArr  = Array.isArray(planRaw)  ? planRaw  : (planRaw.data  || [planRaw]);

const brief = briefArr[0]?.brief_content || '';
const voice = voiceArr[0]?.value || 'Write as Krish Raja. Direct, casual, no fluff. No em dashes. Short paragraphs. Max 120 words outbound.';
const plan  = planArr[0] || {};

// Stale-Plan gating: null or > 72h triggers READ-ONLY mode downstream
const STALE_HOURS = 72;
let plan_stale = false;
if (!plan.last_rendered_at) {
  plan_stale = true;
} else {
  const ageHours = (Date.now() - new Date(plan.last_rendered_at).getTime()) / 3600000;
  plan_stale = ageHours > STALE_HOURS;
}

const planBlock = (plan.current_phase || plan.objective) ? (
  'CURRENT PLAN:\n' +
  (plan.current_phase  ? `Phase: ${plan.current_phase}\n` : '') +
  (plan.objective      ? `Objective: ${plan.objective}\n` : '') +
  (plan.next_milestone ? `Next milestone: ${plan.next_milestone}\n` : '') +
  (plan.blockers       ? `Blockers: ${plan.blockers}\n` : '') +
  (plan.doc_link       ? `Plan doc: ${plan.doc_link}\n` : '') +
  (plan.status         ? `Status: ${plan.status}\n` : '') +
  '\n'
) : '';

const identity_prepend =
  (brief ? 'AGENT BRIEF:\n' + brief + '\n\n' : '') +
  planBlock +
  'VOICE RULES:\n' + voice + '\n\n';

const items = $input.all();
return items.map(item => ({
  json: { ...item.json, identity_prepend, plan_stale }
}));

